void CActionFollowCreature::SetAsSneaking(bool sneaking)
{
    if (Sneaking == sneaking)
        return;
    if (sneaking) {
        if (!GetParentThing().HasTC(TCI_STEALTH)) {
            GetParentThing().AddTC("CTCStealth", false, 0);
            AddedStealthTC = true;
        }
        CTCStealth* stealth;
        GetParentThing().GetTC(&stealth);
