    } else {
        CTCStealth* stealth;
        GetParentThing().GetTC(&stealth);
        stealth->SetSneaking(false);
        CTCCreatureModeManager* modes;
        if (GetParentThing().GetTC(&modes))
            modes->RemoveMode(7);
        if (AddedStealthTC) {
            GetParentThing().RemoveTC(TCI_STEALTH);
            AddedStealthTC = false;
        }
        Sneaking = false;
    }
}

